  await signOut(page);
  await signIn(page, username);
  await openYourOrganizations(page);
  await expect(page.getByRole('link', { name: org, exact: true })).toBeVisible();
  await page.reload();
  await expect(page.getByRole('link', { name: org, exact: true })).toBeVisible();
});

